  }

  public init?(_ other: some RawSyntaxNodeProtocol) {
    guard Self.isKindOf(other.raw) else {
      return nil
    }
    self.init(unchecked: other.raw)
  }

  public init(elements: RawSyntaxNodeList<RawYieldedExpressionSyntax>, arena: __shared RawSyntaxArena) {
    let raw = RawSyntax.makeLayout(
      kind: .yieldedExpressionList,
      childCount: elements.count,
      storage: .flat,
      arena: arena
    ) { layout in
        guard var ptr = layout.baseAddress else {
          return
        }
        for elem in elements.buffer {
          ptr.initialize(to: elem.raw)
          ptr += 1
        }
    }
    self.init(unchecked: raw)
  }

  public var elements: [RawYieldedExpressionSyntax] {
    layoutView.elements.map {
      RawYieldedExpressionSyntax(raw: $0)
    }
  }
}

